SELECT     -- 1. THÔNG TIN MẶT HÀNG CHA (PARENT ITEM / THÀNH PHẨM)    T1.[ItemCode]       AS 'THÀNH PHẨM',    T2.[ItemName]       AS 'TÊN THÀNH PHẨM',    T1.[Version]        AS 'BOM_Version',    T2.[ManBtchNum]     AS 'TP_Quản lý lô (Y/N)',    B2.[ItmsGrpNam]     AS 'TP_Nhóm mặt hàng',    ISNULL(W2.[BalInvntAc], B2.[BalInvntAc]) AS 'TP_Tài khoản kho',     T2.[BuyUnitMsr]     AS 'TP_Đơn vị mua',    T2.[NumInBuy]       AS 'TP_Qty per Purchase Unit', -- Số lượng trên ĐV Mua    T2.[SalUnitMsr]     AS 'TP_Đơn vị bán',    T2.[NumInSale]      AS 'TP_Qty per Sales Unit',    -- Số lượng trên ĐV Bán    T2.[InvntryUom]     AS 'TP_Đơn vị tồn kho',        -- 2. THÔNG TIN THÀNH PHẦN (COMPONENT / NGUYÊN LIỆU)    T1.[POS_ID]         AS 'Position_No',    T1.[ART1_ID]        AS 'Nguyên liệu',    T3.[ItemName]       AS 'Tên Nguyên liệu',    T1.[DESCRIPTION]    AS 'Component_Description',    T3.[ManBtchNum]     AS 'NL_Quản lý lô (Y/N)',    B3.[ItmsGrpNam]     AS 'NL_Nhóm mặt hàng',    ISNULL(W3.[BalInvntAc], B3.[BalInvntAc]) AS 'NL_Tài khoản kho',     T3.[BuyUnitMsr]     AS 'NL_Đơn vị mua',    T3.[NumInBuy]       AS 'NL_Qty per Purchase Unit', -- Số lượng trên ĐV Mua    T3.[SalUnitMsr]     AS 'NL_Đơn vị bán',    T3.[NumInSale]      AS 'NL_Qty per Sales Unit',    -- Số lượng trên ĐV Bán    T3.[InvntryUom]     AS 'NL_Đơn vị tồn kho',        -- 3. SỐ LƯỢNG VÀ KHO    T1.[INPUT_QTY]      AS 'Quantity',     T1.[WhsCode]        AS 'Warehouse'FROM     [BEAS_STL] T1-- 1. Liên kết thông tin Thành phẩm chaLEFT JOIN     [OITM] T2 ON T1.[ItemCode] = T2.[ItemCode] LEFT JOIN    [OITB] B2 ON T2.[ItmsGrpCod] = B2.[ItmsGrpCod]LEFT JOIN    [OITW] W2 ON T2.[ItemCode] = W2.[ItemCode] AND W2.[WhsCode] = T1.[WhsCode]-- 2. Liên kết thông tin Nguyên liệu conLEFT JOIN     [OITM] T3 ON T1.[ART1_ID] = T3.[ItemCode]  LEFT JOIN    [OITB] B3 ON T3.[ItmsGrpCod] = B3.[ItmsGrpCod]LEFT JOIN    [OITW] W3 ON T3.[ItemCode] = W3.[ItemCode] AND W3.[WhsCode] = T1.[WhsCode]WHERE     T1.[ItemCode] IS NOT NULLORDER BY     T1.[ItemCode], T1.[POS_ID]